window.ScripturaLexicons.BDAG_PART_0305 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-01\" data-source=\"BDAG\" data-search=\"προσεργάζομαι verbo ganhar adicionalmente, produzir mais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσεργάζομαι</td><td>verbo</td><td>ganhar adicionalmente, produzir mais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-02\" data-source=\"BDAG\" data-search=\"προσέρχομαι verbo depoente aproximar-se, dirigir-se a, dedicar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσέρχομαι</td><td>verbo depoente</td><td>aproximar-se, dirigir-se a, dedicar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-03\" data-source=\"BDAG\" data-search=\"προσευχή, ῆς, ἡ substantivo feminino oração, lugar de oração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσευχή, ῆς, ἡ</td><td>substantivo feminino</td><td>oração, lugar de oração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-04\" data-source=\"BDAG\" data-search=\"προσεύχομαι verbo depoente orar, dirigir petição à divindade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσεύχομαι</td><td>verbo depoente</td><td>orar, dirigir petição à divindade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-05\" data-source=\"BDAG\" data-search=\"προσέχω verbo acautelar-se, prestar atenção, dedicar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσέχω</td><td>verbo</td><td>acautelar-se, prestar atenção, dedicar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-06\" data-source=\"BDAG\" data-search=\"προσήκω verbo vir, aproximar-se, convir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσήκω</td><td>verbo</td><td>vir, aproximar-se, convir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-07\" data-source=\"BDAG\" data-search=\"προσηλόω verbo pregar, fixar com pregos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσηλόω</td><td>verbo</td><td>pregar, fixar com pregos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-08\" data-source=\"BDAG\" data-search=\"προσήλυτος, ου, ὁ substantivo masculino prosélito, convertido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσήλυτος, ου, ὁ</td><td>substantivo masculino</td><td>prosélito, convertido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-09\" data-source=\"BDAG\" data-search=\"προσηνῶς advérbio bondosamente, gentilmente, amorosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσηνῶς</td><td>advérbio</td><td>bondosamente, gentilmente, amorosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-10\" data-source=\"BDAG\" data-search=\"προσηχέω verbo remissão a προσαχέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσηχέω</td><td>verbo</td><td>remissão a προσαχέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-11\" data-source=\"BDAG\" data-search=\"πρόσθεν advérbio anteriormente, antes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσθεν</td><td>advérbio</td><td>anteriormente, antes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-12\" data-source=\"BDAG\" data-search=\"πρόσθεσις, εως, ἡ substantivo feminino apresentação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσθεσις, εως, ἡ</td><td>substantivo feminino</td><td>apresentação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-13\" data-source=\"BDAG\" data-search=\"πρόσκαιρος, ον adjetivo temporário, transitório BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσκαιρος, ον</td><td>adjetivo</td><td>temporário, transitório</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-14\" data-source=\"BDAG\" data-search=\"προσκαλέω verbo chamar, convocar, convidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκαλέω</td><td>verbo</td><td>chamar, convocar, convidar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-15\" data-source=\"BDAG\" data-search=\"προσκαρτερέω verbo permanecer junto, dedicar-se, perseverar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκαρτερέω</td><td>verbo</td><td>permanecer junto, dedicar-se, perseverar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-16\" data-source=\"BDAG\" data-search=\"προσκαρτέρησις, εως, ἡ substantivo feminino perseverança, paciência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκαρτέρησις, εως, ἡ</td><td>substantivo feminino</td><td>perseverança, paciência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-17\" data-source=\"BDAG\" data-search=\"πρόσκειμαι verbo depoente defectivo estar ligado, estar absorto, dedicar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσκειμαι</td><td>verbo depoente defectivo</td><td>estar ligado, estar absorto, dedicar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-18\" data-source=\"BDAG\" data-search=\"προσκεφάλαιον, ου, τό substantivo neutro travesseiro, almofada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκεφάλαιον, ου, τό</td><td>substantivo neutro</td><td>travesseiro, almofada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-19\" data-source=\"BDAG\" data-search=\"προσκληρόω verbo associar-se, ligar-se, juntar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκληρόω</td><td>verbo</td><td>associar-se, ligar-se, juntar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0305-20\" data-source=\"BDAG\" data-search=\"πρόσκλησις substantivo feminino remissão a πρόσκλισις BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσκλησις</td><td>substantivo feminino</td><td>remissão a πρόσκλισις</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0305-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσεργάζομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσεργάζομαι</span> 1.º aor. <span class=\"greek\">προσηργασάμην</span> ou <span class=\"greek\">προσειργασάμην</span>—B-D-F §67, 3; v. também Mlt-H. 189f (Eur., Hdt. et al.; pap; vários sentidos) ganhar adicionalmente, produzir mais (X., Hell. 3, 1, 28; PCairZen 509, 13) <span class=\"greek\">ἡ</span> <span class=\"greek\">μνᾶ</span> <span class=\"greek\">σου</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">προσηργάσατο</span> <span class=\"greek\">μνᾶς</span> tua mina produziu dez minas a mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:16</a>.—DELG s.v. <span class=\"greek\">ἔργον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσέρχομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσέρχομαι</span> depoente médio; imperf. <span class=\"greek\">προσηρχόμην</span>; fut. <span class=\"greek\">προσελεύσομαι</span>; 2.º aor. <span class=\"greek\">προσῆλθον</span> (também <span class=\"greek\">προσῆλθα</span> B-D-F §81, 3; Mlt-H. 208); perf. <span class=\"greek\">προσελήλυθα</span>; mais-que-perf. 1.ª pl. <span class=\"greek\">προσεληλύθειμεν</span> (Just., A II, 2, 3) (Aeschyl., Hdt.+) primordialmente ‘vir, ir a, aproximar-se’.</p><p class=\"entry-text\">① mover-se em direção a</p><p class=\"entry-text\">ⓐ de movimento físico: vir/ir a, aproximar-se (esp. frequente em Mt, cerca de 50 vezes; v. JEdwards, JBL 106, ’87, 65–74) com dat. de pessoa (X., Cyr. 1, 4, 27; Aelian, VH 9, 3, final; En 14:25; Jos., Ant. 12, 19; Just., D. 2, 4 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:1</a>; 8:5; 9:14 al.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:52</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:1</a>; 10:28 ‘visitar’; 18:2; MPol 16:1; GJs 20:4 (deStrycker; sem dat. Tdf.). Com dat. de lugar (Herodian 2, 6, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:18</a>, 22; AcPl Ha 11, 13; <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱερουσαλήμ</span> 8, 30. Uso absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:29</a>; 20:5 v.l. (v. CMaurer, TZ, 3, ’47, 321–37). MPol 4. Incerto AcPl Ha 2, 2. O part. é frequentemente usado com verbos que denotam uma atividade, para dar vivacidade à narrativa <span class=\"greek\">προσελθὼν</span> <span class=\"greek\">εἶπεν</span> (cf. BGU 587, 2 [II a.C.]; Jos., Ant. 9, 194) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:3</a>; 8:19; 18:21; v. também 13:10; 15:12; 25:20, 22, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:35</a>; 14:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:12</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">προσεκύνει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:2</a>; 9:18 v.l., et al. <span class=\"greek\">πρ</span>. <span class=\"greek\">ἔπεσεν</span> 26:39 v.l.; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:35</a> v.l., et al. (v. <span class=\"greek\">προέρχομαι</span> 1). Seguido de inf. que denota finalidade (1 Macc 2:23) <span class=\"greek\">προσῆλθον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μαθηταὶ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐπιδεῖξαι</span> seus discípulos aproximaram-se para mostrar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:1</a>. <span class=\"greek\">προσερχομένου</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κατανοῆσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:31</a>. Cf. 12:13.</p><p class=\"entry-text\">ⓑ de aproximação ou entrada na presença de uma divindade, sentido figurado de 1a: aproximar-se (Cass. Dio 56, 9, 2 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">προσερχώμεθα</span>; PGiss 20, 24=Mitt-Wilck. I/2, 94; Jer 7:16; Sir 1:28 <span class=\"greek\">μὴ</span> <span class=\"greek\">προσέλθῃς</span> <span class=\"greek\">αὐτῷ</span> [=<span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>] <span class=\"greek\">ἐν</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">δισσῇ</span>; Philo, Plant. 64, Deus Imm. 8; Tat. 18, 2; Ath. 18, 1) <span class=\"greek\">πρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a>; 11:6; cf. 1 Cl 23:1; 29:1. Com dat. de lugar <span class=\"greek\">τῷ</span> <span class=\"greek\">θρόνῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a>. Também em uso absoluto <span class=\"greek\">προσέρχεσθαι</span> significa aproximar-se de Deus em sentido cultual. 10:1, 22. Alguns sustentam que <span class=\"greek\">πρ</span>. em Hb pode conotar a ideia forense ‘comparecer em juízo’ (POxy 40, 4 [II/III d.C.]; 2783, 25 [III d.C.]; PRyl 234, 6 [II d.C.]). O aspecto cultual provavelmente fornece a chave para o uso absoluto <span class=\"greek\">πυκνότερον</span> <span class=\"greek\">προσερχόμενοι</span> 2 Cl 17:3.—A Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:3</a> (de prosélitos, FDanker, ZNW 58, ’67, 95f; com <span class=\"greek\">πρός</span> como Lucian, Ver. Hist. 2, 28; Ex 34:32; Josh 14:6).</p><p class=\"entry-text\">ⓒ de coisas inanimadas, sobrevir, sentido transferido de 1a (Soph. et al.; cf. Eur., Or. 859 <span class=\"greek\">προσῆλθεν</span> <span class=\"greek\">ἐλπίς</span>; BGU 614, 21) <span class=\"greek\">πρ</span>. <span class=\"greek\">τινί</span> algo sobrevém a alguém ou se apodera de alguém <span class=\"greek\">φρίκη</span> <span class=\"greek\">μοι</span> <span class=\"greek\">προσῆλθεν</span> Hv 3, 1, 5. <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἰσχυρότης</span> 3, 12, 3. Sem dat., facilmente suprido pelo contexto m 5, 1, 3.</p><p class=\"entry-text\">② aplicar-se a algo, voltar-se para, ocupar-se de algo (Diod S 1, 95, 1 <span class=\"greek\">τοῖς</span> <span class=\"greek\">νόμοις</span>; Plut., Cato Min. 764 [12, 2]; Epict. 4, 11, 24; pap; Sir 4:15 v.l.; 6:19, 26; Philo, Agr. 123, Migr. Abr. 86 <span class=\"greek\">ἀρετῇ</span>; Just., D. 112, 5 <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφητικοῖς</span> <span class=\"greek\">λόγοις</span>; PYale 83, 15) <span class=\"greek\">οὐ</span> <span class=\"greek\">προσελεύσῃ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">προσευχήν</span> <span class=\"greek\">σου</span> D 4:14; dedicar-se a <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσέρχεται</span> <span class=\"greek\">ὑγιαίνουσιν</span> <span class=\"greek\">λόγοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a> (v. <span class=\"greek\">προσέχω</span> 2b). <span class=\"greek\">πρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) 1 Cl 33:8.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσευχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσευχή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span></p><p class=\"entry-text\">① petição dirigida a uma divindade, oração (pap politeísta BGU 1080, 4 [III d.C.] <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κοινὰς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">εὐχὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσευχάς</span>; LXX; pseudepigr.; Jos., Bell. 5, 388, com menor probabilidade [v. 2] C. Ap. 2, 10, Ant. 14, 258) IEph 1:2; 5:2; 10:2; 11:2; IMg 14:1; IPhld 5:1; ISm 11:1, 3. <span class=\"greek\">αἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:8</a>; 8:3f.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:7</a>. Com <span class=\"greek\">δέησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:6</a>; IMg 7:1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1</a>; 5:5 (v. <span class=\"greek\">δέησις</span>). Com <span class=\"greek\">εὐχαριστία</span> ISm 7:1. Com <span class=\"greek\">ἐλεημοσύναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:4</a>; <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρ</span>. IPol 7:1; <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρ</span>. Phlm 22; <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">πρ</span>. mediante oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:29</a>; IEph 20:1; IPhld 8:2; em oração IRo 9:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πρ</span>. nas orações IMg 14:1; ITr 13:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:12</a>. Com o mesmo sentido <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:2</a>; Phlm 4; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρ</span>. IPhld 10:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> oração a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:12</a>. Também <span class=\"greek\">πρ</span>. <span class=\"greek\">γινομένη</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:5</a>; cf. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> AcPl Ha 6, 9 (<span class=\"greek\">πρ</span>. <span class=\"greek\">πρός</span> como Ps 68:14). <span class=\"greek\">ὥστε</span> … <span class=\"greek\">ἐκτενῆ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Παύλῳ</span> de modo que todos dirigiam fervorosas orações em favor de Paulo AcPl Ha 6, 7. Com <span class=\"greek\">νηστεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:29</a> v.l. O jejum é declarado melhor que a oração 2 Cl 16:4a. A oração procedente de boa consciência salva da morte, v. 4b; expulsa demônios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:29</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀναφέρειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> (<span class=\"greek\">ἀναφέρειν</span> <span class=\"greek\">προσευχάς</span> Orig., C. Cels. 8, 73, 32; v. <span class=\"greek\">ἀναφέρω</span> 3) 2 Cl 2:2; <span class=\"greek\">προσκαρτερεῖν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:42</a>; 6:4 (com <span class=\"greek\">τῇ</span> <span class=\"greek\">διακονίᾳ</span>). <span class=\"greek\">ἐκπεσεῖν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. AcPl Ha 2, 8. <span class=\"greek\">σχολάζειν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a> (sobre oração e abstinência v. TestNapht 8:8); v. IPol 1:3. <span class=\"greek\">νήφειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">προσευχάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:7</a>; <span class=\"greek\">καταπαύειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρ</span>. MPol 8:1; <span class=\"greek\">ἀναπαύειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρ</span>. AcPl Ha 4, 32. <span class=\"greek\">αἰτεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:22</a>. <span class=\"greek\">προσευχῇ</span> <span class=\"greek\">προσεύχεσθαι</span> orar fervorosamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:17</a>. Em posição ajoelhada ou prostrado no chão; daí <span class=\"greek\">ἀναστὰς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:45</a>; <span class=\"greek\">ἐγείρεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. Hv 2, 1, 3; <span class=\"greek\">εἰσηκούσθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:31</a>; <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">πρ</span>. AcPl Ha 2, 14. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. 4, 28. Oração pública, comunitária <span class=\"greek\">ἡ</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">πρ</span>. ITr 12:2. <span class=\"greek\">αἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> intercessões a Deus em favor de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:30</a>; <span class=\"greek\">ὥρα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:1</a> (v. <span class=\"greek\">ἔνατος</span> e a bibliografia ali indicada.—Sobre horário fixo de oração v. Marinus, Vi. Procli 24 <span class=\"greek\">καιρὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">εὐχῶν</span>; também 22, final). <span class=\"greek\">οἶκος</span> <span class=\"greek\">προσευχῆς</span> (=<span lang=\"he\" dir=\"rtl\">בֵּית־תְּפִלָּה</span> Is 56:7) casa de oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:46</a>. Sobre <span class=\"greek\">προσέρχεσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">προσευχήν</span> D 4:14 v. <span class=\"greek\">προσέρχομαι</span> 2. Cf. B 19:12.—Para bibliografia v. <span class=\"greek\">προσεύχομαι</span>, final.</p><p class=\"entry-text\">② lugar de oração ou destinado à oração, lugar de oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:13</a>, 16. Usada esp. entre judeus, esta palavra é quase sempre equivalente a <span class=\"greek\">συναγωγή</span> no sentido de lugar de culto (v. <span class=\"greek\">συναγωγή</span> 2a; SKrauss, Pauly-W. 2 ser. IV, ’32, 1287f; ins New Docs 3, 121f; 4, 201f). Mas muitos consideram que a <span class=\"greek\">πρ</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:13</a>, 16 não era uma sinagoga regular porque era frequentada apenas por mulheres (v. 13), e porque a palavra <span class=\"greek\">συν</span>. é frequentemente usada em outros lugares de Ac (p. ex. 17:1, 10, 17); a <span class=\"greek\">πρ</span>. em nossa passagem pode ter sido um local informal de reunião, talvez ao ar livre (v. BSchwank VD 3, ’55, 279).—Nos raros casos em que um local politeísta de oração é chamado <span class=\"greek\">πρ</span>., é quase sempre possível a influência judaica (refs. de literatura, ins e pap em Schürer II 425f; 439–47; Mayser I/32 ’36 p. 19; Boffo, Iscrizioni 39–60. V. também 3 Macc 7:20 al.; SEG VIII, 366, 6 [II a.C.], também refs. em XLII, 1849; Dssm., NB 49f [BS 222f]; MStrack, APF 2, 1903, 541f; Philo; talvez Jos., C. Ap. 2, 10 e Ant. 14, 258 [posições contraditórias sobre este último em Schürer II 441, 65 e 444, 76]; Elbogen2 445; 448; 452; SZarb, De Judaeorum <span class=\"greek\">προσευχή</span> in Act. 16:13, 16: Angelicum 5, 1928, 91–108; também <span class=\"greek\">συναγωγή</span> 2). Mas tal influência deve ser excluída no caso da ins de Epidauro do IV a.C. (IG IV2/1, 106 I, 27), onde a forma dórica de <span class=\"greek\">προσευχή</span> ocorre no sentido ‘lugar de oração’: <span class=\"greek\">ποτευχὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βωμός</span>. Por conseguinte, também é improvável em IPontEux I2, 176, 7 e em Artem. 3, 53 p. 188, 27; 189, 2.—RAC VIII 1134–1258; IX 1–36; BHHW I 518–23. MHengel, Proseuche u. Synagoge, KGKuhn Festschr., ’71, 157–84; Schürer II 423–63.—DELG s.v. <span class=\"greek\">εὔχομαι</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσεύχομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσεύχομαι</span> imperf. <span class=\"greek\">προσηυχόμην</span>; fut. <span class=\"greek\">προσεύξομαι</span>; 1.º aor. <span class=\"greek\">προσηυξάμην</span> (sobre o aumento v. W-H., App. 162; Tdf., Prol. 121; B-D-F §67, 1; Mlt-H. 191f) depoente médio; dirigir petição à divindade, orar (Aeschyl., Hdt.+; PEdg 7 [=Sb 6713], 10 [257 a.C.]; Sb 3740 [I d.C.] <span class=\"greek\">Ἄττηος</span> <span class=\"greek\">προσεύχεται</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἀβύδῳ</span> <span class=\"greek\">θεοῖς</span>; LXX; pseudepigr.; Philo, Joseph.; Ar. [Milne 76, 37f]; Ath. 11, 2) uso absoluto (Demochares [300 a.C.]: 75 Fgm. 2 Jac.; Dio Chrys. 35 [52], 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:5</a>–7; 14:23; 26:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:35</a>; 6:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:10</a>; 5:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:24</a>; 6:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:4f</a> (sobre a questão de cobrir a cabeça v. PTomson, Paul and the Jewish Law [CRINT III/1] ’90); 14:14b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:8</a> (sobre a questão da oração pelos gentios v. Schürer II 311f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:13</a>, 18; MPol 5:2; 7:3; 12:3; Hv 1, 1, 4; 3, 1, 6; 5:1; Hs 9, 11, 7a; D 8:2. AcPl Ha 1, 32; 2, 12; 4, 23; 7, 19; 11, 14 (reconstituído) e 22; AcPlCor 2:30. Seguido de oração introduzida por <span class=\"greek\">λέγων</span> (Is 44:17; cf. Did., Gen. 223, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:41</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a> (sobre a oração do Senhor v. TManson, The Sayings of Jesus ’54, 165–71; EGrässer, D. Problem der Parusieverzögerung, ’57, 95–113; HBetz, Essays on the Sermon on the Mount ’85, SM 370–86 [bibliografia]). Com dat. da pessoa a quem se dirige a oração (assim predominantemente fora de nossa literatura; v. B-D-F §187, 4; cf. Rob. 538) <span class=\"greek\">πρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> orar a Deus (Diod S 13, 16, 7 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; Chariton 3, 10, 6 <span class=\"greek\">θεῷ</span>; Athen. 13, 32, 573d <span class=\"greek\">τῇ</span> <span class=\"greek\">θεῷ</span>; Philostrat., Vi. Apollon. 5, 28 p. 186, 9 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; Jos., Ant. 10, 252; cf. 256; <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">θεῷ</span> Orig., C. Cels. 8, 26, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:13</a>; <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">πρ</span>. (TestJos 3:3; 7:4) Hv 1, 1, 3; 2, 1, 2; <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:6b</a>. Também <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> (LXX; ParJer 6:1) Hv 1, 1, 9. <span class=\"greek\">πρὸς</span> <span class=\"greek\">κύριον</span> GJs 20:2 (pap, não codd.; mas 2:4 codd., não pap). Com dat. de modo <span class=\"greek\">πρ</span>. <span class=\"greek\">γλώσσῃ</span>, <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span>, <span class=\"greek\">τῷ</span> <span class=\"greek\">νοί̈</span> orar em língua, em espírito, com entendimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:14a</a>, 15; <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 20</a> (v. Borger, GGA 140); <span class=\"greek\">προσευχῇ</span> <span class=\"greek\">πρ</span>. orar fervorosamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:17</a>. <span class=\"greek\">ἀδιαλείπτως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:17</a>; IEph 10:1; Hs 9, 11, 7b. <span class=\"greek\">ἀδεῶς</span> MPol 7:2a. <span class=\"greek\">πρ</span>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> orar por alguém ou algo (Philostrat., Vi. Apoll. 8, 26 p. 340, 5; LXX; ApcMos 36; Ath.; Hippol., Ref. 9, 23, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:14</a> e Plut., Mor. 275d); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:9</a>; IEph 10:1; 21:2; ISm 4:1; D 1:3. Também <span class=\"greek\">πρ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (LXX; v. <span class=\"greek\">περί</span> 1f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a>; ITr 12:3; MPol 5:1; D 2:7; GJs 8:2. Seguido de <span class=\"greek\">ἵνα</span> (B-D-F §392, 1c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:20</a>; 26:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:18</a>; 14:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:40</a>, 46. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:9</a>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:11</a>; 3:1. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ὅπως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:15</a>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ὅπως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:16</a> v.l. Seguido de gen. do inf. com art. (B-D-F §400, 7; Rob. 1094) <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βρέξαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:17</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (<span class=\"greek\">ἐπί</span> 1c<span class=\"greek\">γ</span>) v. 14 (cf. Marinus, Vi. Procli 20b: Proclo, em seu leito de morte, faz seus amigos recitarem-lhe hinos). Seguido de acus., referente ao conteúdo ou modo da oração (Philostrat., Vi. Apoll. 6, 18 p. 229, 32) <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:11</a>. <span class=\"greek\">μακρὰ</span> <span class=\"greek\">πρ</span>. fazer longas orações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a>.—Com acus. da coisa pedida em oração <span class=\"greek\">πρ</span>. <span class=\"greek\">τι</span> orar por algo (X., Hell. 3, 2, 22 <span class=\"greek\">νίκην</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:26</a> (sobre a capacidade da pessoa comum de orar v. Philosoph. Max. p. 497, 7 <span class=\"greek\">μόνος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σοφὸς</span> <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">εὔχεσθαι</span>=só o sábio sabe orar).—FHeiler, Das Gebet5 1923 (bibliografia); FDölger, Sol Salutis: Gebet u. Gesang im christl. Altert.2 1925 (material da história das religiões); JDöller, Das G. im AT in rel.-gesch. Beleuchtung 1914; AGreiff, Das G. im AT 1915; JHempel, G. u. Frömmigkeit im AT 1922, Gott u. Mensch im AT2 ’36; Elbogen2 353ff; 498ff.—EvdGoltz, Das G. in der ältesten Christenheit 1901; IRohr, Das G. im NT 1924; JMarty, La Prière dans le NT: RHPR 10, 1930, 90–98; JNielen, G. u. Gottesdienst im NT ’37; HGreeven, G. u. Eschatologie im NT ’31. LRuppoldt, D. Theol. Grundlage des Bittgebetes im NT, diss. Leipzig ’53; AHamman, La Prière, I (NT), ’59.—JoachJeremias, D. Gebetsleben Jesu: ZNW 25, 1926, 123–40; AJuncker, Das G. bei Pls 1905, Die Ethik des Ap. Pls II 1919, 55–72; CSchneider, <span class=\"greek\">Αγγελος</span> IV ’32, 11–47 (Paulo); EOrphal, Das Plsgebet ’33; J-AEschlimann, La Prière dans S. Paul ’34; GHarder, Pls u. d. Gebet ’36; AKlawek, Das G. zu Jesus 1921; AFrövig, D. Anbetung Christi im NT: TTK 1, 1930, 26–44; EDelay, A qui s’adresse la prière chr.? RTP 37, ’49, 189–201.—OHoltzmann, Die tägl. Gebetsstunden im Judentum u. Urchristentum: ZNW 12, 1911, 90–107, HWagenvoort, Orare: Precari: Verbum, HWObbink Festschr., ’64, 101–11 (oração entre os romanos); RMerkelbach, MTotti, eds., Abrasax: Ausgewählte Papyri religiösen u. magischen Inhalts, I: Gebete ’90; FHickson, Roman Prayer Language ’93; JCharlesworth, ed., The Lord’s Prayer and Other Prayer Texts fr. the Greco-Roman Era ’94 (bibliografia 186–201); MKiley, ed., Prayer fr. Alexander to Constantine (somente trad.) ’97.—B. 1471. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσέχω</span> imperf. <span class=\"greek\">προσεῖχον</span>; fut. <span class=\"greek\">προσέξω</span> LXX; 2.º aor. <span class=\"greek\">προσέσχον</span> (1 Cl 4:2=Gen 4:5); perf. <span class=\"greek\">προσέσχηκα</span>; mais-que-perf. 2.ª pl. <span class=\"greek\">προσεσχήκειτε</span> (Just., D. 64, 3); adj. verbal neutro <span class=\"greek\">προσεχτέον</span> (TestSol 13:1 C) (Aeschyl., Hdt.+). Nos escritos não bíblicos, o sentido primário é ‘ter em estreita proximidade’; frequentemente ativo, como na maior parte de nossa literatura, de processos mentais: ‘dirigir a mente para’ (assim na expressão <span class=\"greek\">πρ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">τινι</span> Aristoph. et al.; Just., D. 64, 3 al.; mas também frequentemente sem <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span> X. et al., igualmente Wsd 8:12; 1 Macc 7:11; 4 Macc 1:1).</p><p class=\"entry-text\">① estar em estado de alerta, preocupar-se com, cuidar de, tomar cuidado, com dat. <span class=\"greek\">χήρᾳ</span>, <span class=\"greek\">ὀρφανῷ</span> B 20:2. <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποιμνίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:28</a> (Sb IV, 7353, 9f [200 d.C.] um filho aconselha sua mãe a cuidar de si mesma e a não se inquietar [<span class=\"greek\">διστάζειν</span>] por ele, pois está em bom lugar).—<span class=\"greek\">προσέχειν</span> <span class=\"greek\">ἑαυτῷ</span> tomar cuidado, estar de sobreaviso (Plut., Mor. 150b <span class=\"greek\">νήφων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσέχων</span> <span class=\"greek\">ἑαυτῷ</span>; Gen 24:6; Ex 10:28; 34:12; Dt 4:9; 6:12 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:3</a>; B 4:6. Seguido de inf. 2:1. Seguido de <span class=\"greek\">μήποτε</span> cuidar para que … não, ou acautelar-se para que não … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:34</a>. Seguido de <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> acautelar-se de algo, estar de sobreaviso contra algo (TestLevi 9:9; TestDan 6:1.—B-D-F §149; Rob. 577) 12:1. <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">τί</span> <span class=\"greek\">μέλλετε</span> <span class=\"greek\">πράσσειν</span> atentai para o que pretendeis fazer a estes homens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:35</a> (sobre a função de <span class=\"greek\">ἐπί</span> aqui, v. <span class=\"greek\">ἐπί</span> 14a).—O pronome reflexivo também pode ser omitido (cf. UPZ 69, 7 [152 a.C.] <span class=\"greek\">προσέχω</span> <span class=\"greek\">μή</span>; 2 Ch 25:16; Sir 13:8) <span class=\"greek\">προσέχωμεν</span> <span class=\"greek\">μήποτε</span> B 4:14. <span class=\"greek\">προσέχετε</span> <span class=\"greek\">μήπως</span> Ox 840, 2 (Unknown Sayings 93f). <span class=\"greek\">προσέχειν</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> acautelar-se de alguém ou algo (Sir 6:13; 11:33; 17:14; 18:27; Syntipas p. 94, 28 <span class=\"greek\">πρόσεχε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πολιτῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:15</a>; 10:17; 16:6, 11f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:46</a>; D 6:3; 12:5. Seguido de <span class=\"greek\">μή</span> e inf. cuidar para não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:1</a>.</p><p class=\"entry-text\">② prestar estreita atenção a algo, prestar atenção a, dar ouvidos a, seguir</p><p class=\"entry-text\">ⓐ com dat. de pessoa (Polyb. 6, 37, 7; Cass. Dio 58, 23, 2; Diog. L. 1, 49; Jos., Bell. 1, 32, Ant. 8, 34; 264) <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπισκόπῳ</span> IPhld 7:1; IPol 6:1. <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφήταις</span> ISm 7:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:10f</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">φυσιοῦσίν</span> <span class=\"greek\">με</span> dar ouvidos aos que me ensoberbecem ITr 4:1. <span class=\"greek\">πρ</span>. <span class=\"greek\">πνεύμασι</span> <span class=\"greek\">πλάνοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1</a>.</p><p class=\"entry-text\">ⓑ com dat. de coisa <span class=\"greek\">προσεῖχε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πετάλῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱερέως</span> ele (Joaquim) atentou para a lâmina frontal do sacerdote GJs 5:1. Dar atenção a palavras ou instrução (Mnesimachus Com. [IV a.C.] 4, 21 <span class=\"greek\">πρόσεχ</span>’ <span class=\"greek\">οἷς</span> <span class=\"greek\">φράζω</span>; Plut., Mor. 362b; PPetr II, 20 II, 1 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιστολῇ</span>; 1 Macc 7:11; Jos., Ant. 8, 241 <span class=\"greek\">τ</span>. <span class=\"greek\">λόγοις</span>; TestZeb 1:2; Just., D. 10, 1; Tat. 12, 3; Ath. 7, 3) <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">λεγομένοις</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Φιλίππου</span> prestar atenção ao que era dito por Filipe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:6</a> (<span class=\"greek\">λέγω</span> 1b<span class=\"greek\">κ</span>); cf. 16:14. <span class=\"greek\">πρ</span>. <span class=\"greek\">μύθοις</span> (Ps.-Plut., Pro Nobilitate 21, final <span class=\"greek\">τοῖς</span> <span class=\"greek\">Αἰσωπικοῖς</span> <span class=\"greek\">μύθοις</span> <span class=\"greek\">προσέχοντες</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:14</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a>. <span class=\"greek\">ἐμαῖς</span> <span class=\"greek\">βουλαῖς</span> 1 Cl 57:5 (Pr 1:30); cf. 57:4 (Pr 1:24; devendo-se suprir o dat. <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span>).—1 Cl 2:1; 2 Cl 19:1; MPol 2:3. (<span class=\"greek\">τούτοις</span>) <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐνετείλατο</span> <span class=\"greek\">προσέχετε</span> B 7:6.—Médio: apegar-se a, aderir a, com dat. de coisa (lit. e fig. Trag., Hdt.+) <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσέχεται</span> <span class=\"greek\">ὑγιαίνουσιν</span> <span class=\"greek\">λόγοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a> v.l.</p><p class=\"entry-text\">ⓒ uso absoluto: prestar atenção, estar alerta, notar (Demosth. 21, 8; Diod S 20, 21, 2 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">προσεῖχεν</span>; PMagd 22, 5 [221 a.C.]; Sir 13:13) 2 Cl 17:3; B 4:9; B 7:9. <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἀκριβῶς</span> prestai estreita atenção 7:4. Seguido de pergunta indireta: <span class=\"greek\">πῶς</span> 7:7. <span class=\"greek\">τί</span> 15:4. <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἵνα</span> cuidai para que 16:8.—<span class=\"greek\">προσέχετε</span> como v.l. de <span class=\"greek\">προσεύχεσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a>.</p><p class=\"entry-text\">ⓓ <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">θυσίαις</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">προσέσχεν</span> (Deus) não deu atenção aos sacrifícios (de Caim) 1 Cl 4:2 (Gen 4:5).</p><p class=\"entry-text\">③ continuar a prestar estreita atenção a algo, ocupar-se de, dedicar-se ou aplicar-se a, com dat. (Hdt. et al.; Demosth. 1, 6 <span class=\"greek\">τῷ</span> <span class=\"greek\">πολέμῳ</span>; Herodian 2, 11, 3 <span class=\"greek\">γεωργίᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνῃ</span>; POxy 531, 11 [II d.C.] <span class=\"greek\">τοῖς</span> <span class=\"greek\">βιβλίοις</span> <span class=\"greek\">σου</span>) <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀναγνώσει</span> <span class=\"greek\">κτλ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:13</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θυσιαστηρίῳ</span>, oficiar no altar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:13</a>. <span class=\"greek\">οἴνῳ</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">πρ</span>. ser viciado em muito vinho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:8</a> (Polyaenus, Strateg. 8, 56 <span class=\"greek\">τρυφῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέθῃ</span>).—M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσήκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσήκω</span> fut. <span class=\"greek\">προσήξω</span> (Aeschyl., Thu.+; ins, pap, LXX; TestJud 5:2; JosAs; EpArist 29; Philo; Jos., Bell. 7, 450; Just.; Tat. 31, 1; Ath. 9, 2, R. 1 p. 49, 2 al.).</p><p class=\"entry-text\">① em sentido espacial, vir de modo a estar presente, vir a, aproximar-se, com dat. de pessoa (Dio Chrys. 65 [15], 2) IRo 9:3, de congregações que não estavam no itinerário de Inácio.—<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">προσευχήν</span> vir para oração B 19:12.</p><p class=\"entry-text\">② qualitativamente, ser apropriado em determinada circunstância, convir, ser adequado, próprio, ser dever de alguém (Trag., Thu. et al.; Jos., Ant. 13, 432 <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσήκοντα</span>) <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">προσῆκον</span> conforme convém (Plut., Mor. 122a; OGI 90, 18 [196 a.C.]; PCairMasp 167, 16; frequente em documentos cívicos em referência a um elevado padrão de conduta, v. SIG IV ind.) MPol 10:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσηλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσηλόω</span> 1.º aor. <span class=\"greek\">προσήλωσα</span>; pass. perf. part. pl. <span class=\"greek\">προσηλωμένοι</span> (3 Macc 4:9) (Pla. et al.; ins; Philo, De Prov. Fgm. 2 [Eus., PE 8, 14, 24]; Jos., Ant. 5, 208; Just., A I, 58, 3; Mel., P. 76, 556; 80, 591) pregar (firmemente) <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> algo a algo (Diod S 4, 47, 5), um título de dívida à cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:14</a> (v. Dibelius, Lohmeyer ad loc.; FDölger, Die Sonne der Gerechtigkeit und d. Schwarze 1918, 129ff.—<span class=\"greek\">πρ</span>. <span class=\"greek\">σταυρῷ</span>=‘crucificar’ Diod S 2, 18, 1; Artem. 2, 56; Jos., Bell. 2, 308; Galen, De Usu Part. II 214, 8 Helmr.). Pregar firmemente o condenado à pira MPol 13:3 (o sentido mais geral ‘fixar’ [Jos., Bell. 5, 232] é excluído pela menção específica de pregos). Talvez aqui no sentido de acorrentar firmemente (cf. Lucian, Prometh. 2 <span class=\"greek\">κατάκλειε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσήλου</span>, Dial. Deor. 1, 1).—DELG s.v. <span class=\"greek\">ἧλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσήλυτος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσήλυτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (cf. <span class=\"greek\">ἦλθον</span>; também <span class=\"greek\">ἔλευσις</span>) aquele que passou do politeísmo à religião e à prática judaicas, convertido (assim Goodsp., Probs. 36f; a forma transliterada ‘proselyte’ NRSV, REB, mas somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:11</a>, nos demais casos ‘convert’ ou ‘worshiper’), designação de um gentio conquistado para a comunidade israelita por esforços missionários (a palavra é encontrada em Apollon. Rhod. 1, 834 [<span class=\"greek\">μετοίκους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσηλύτους</span>] e na LXX. Claramente em sentido técnico em Philo; cf. Spec. Leg. 1, 51 <span class=\"greek\">τούτους</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καλεῖ</span> <span class=\"greek\">προσηλύτους</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσεληλυθέναι</span> <span class=\"greek\">καινῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φιλοθέῳ</span> <span class=\"greek\">πολιτείᾳ</span>=a estes ele [aparentemente Moisés] chama ‘prosélitos’ porque ‘se tornaram prosélitos’, passando a uma nova ordem comunitária em que prevalece o amor a Deus; Sb 1742 <span class=\"greek\">Σάρρα</span> <span class=\"greek\">προσήλυτος</span>. Inscrições funerárias romanas também contêm ‘proselytus’ ou ‘proselyta’ [Schürer III 162, 55].—Talvez <span class=\"greek\">πρ</span>. fosse usado como termo técnico no culto de Ísis [=lat. ‘advena’ em Apuleius, Metam. 11, 26; v. Rtzst., Mysterienrel.3 193]). Com <span class=\"greek\">Ἰουδαῖοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:11</a>. De Nicolau de Antioquia 6:5. Dos esforços judaicos de proselitismo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:15</a>.—Devem ser diferenciados dos <span class=\"greek\">σεβόμενοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, que se haviam obrigado apenas a observar certos mandamentos; numa expressão mista <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a> fala de <span class=\"greek\">σεβόμενοι</span> <span class=\"greek\">πρ</span>.—ABertholet, Die Stellung der Israeliten u. der Juden zu den Fremden 1896, 257ff; KAxenfeld, Die jüd. Propaganda als Vorläuferin der urchristl. Mission: Missionswissenschaftl. Studien für GWarneck 1904, 1–80; ILevi, Le Prosélytisme juif: REJ 50, 1905, 1 ff; 51, 1906, 1ff; 53, 1907, 56ff; Schürer III 150–76; HGressmann, ZMR 39, 1924, 10ff; 169ff; MMeinertz, Jesus u. die Heidenmission2 1925; Bousset, Rel.3 76ff; Billerb. I 924ff; II 715; IV 353ff; Harnack, Mission I4 1923, 1–23 (trad. ingl., JMoffatt2, 1908, 1–23); GRosen, Juden u. Phönizier 1929; GMoore, Judaism I, 1927, 323–53; FDerwacter, Preparing the Way for Paul 1930; HLietzmann, Gesch. d. Alten Kirche 1, ’32, 68–101; CSchneider, Ntl. Zeitgeschichte ’34, 173–75; HPreisker, Ntl. Zeitgesch. ’37, 290–93; WBraude, Jewish Proselyting in the First Five Centuries of the Common Era ’40; SLieberman, Greek in Jewish Palestine ’42: Gentiles and Semi-Proselytes, 68–90; JKlausner, From Jesus to Paul (trad. WStinespring)’43, 31–49; ESimon, Verus Israel ’48; SZeitlin, Proselytes and Proselytism, etc.: HAWolfson-Festschr. ’65, 871–81. Bibliografia adicional, esp. desde ’65, Schürer III 1–3; ABD V 505.—Pauly-W., Suppl. IX, 1248–83; Kl. Pauly IV, 1187; BHHW IV 1515.—V. também bibliografia s.v. <span class=\"greek\">σέβω</span> 1b.—DELG s.v. <span class=\"greek\">ἐλεύσομαι</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσηνῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσηνῶς</span> (cf. o antônimo homérico <span class=\"greek\">ἀπηνής</span> ‘rude’; Theophr.; Diod S 5, 44, 6 et al.) adv. de <span class=\"greek\">προσηνής</span>, <span class=\"greek\">ές</span> (Pind., Hdt. et al.; SIG 783, 29; Pr 25:25; Philo; Jos., Bell. 3, 507; Mel., P. 11, 72) relativo a estar benevolamente disposto, bondosamente, gentilmente, amorosamente, com <span class=\"greek\">ἠπίως</span>, de Deus (Orph. Hymns 2, 5; 40, 12; 60, 7 Qu. empregam o adj. para caracterizar deusas) 1 Cl 23:1.—DELG s.v. <span class=\"greek\">προσηνής</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσηχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσηχέω</span> v. <span class=\"greek\">προσαχέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσθεν</span> adv. (antônimo de <span class=\"greek\">ὄπισθεν</span>; Hom. et al.; ins, pap; Jos., Ant. 14, 370; 463; SibOr 3, 391) em nossa literatura somente de tempo: relativo a um período de tempo anterior a outro período de tempo, anterior, precedente <span class=\"greek\">ὁ</span> <span class=\"greek\">πρόσθεν</span> <span class=\"greek\">χρόνος</span> o tempo anterior (X.; SIG 85, 11; 136, 6; 165, 13) Dg 9:1, 6.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσθεσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσθεσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προστίθημι</span>; Thu. et al.; ins, pap, LXX, Philo, em todos os casos em sentido diferente do NT, como ‘aplicação’ etc.; p. ex. Polyaenus 2, 3, 8 <span class=\"greek\">πρόσθεσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>=‘presença [auxiliadora] de Deus’) apresentação <span class=\"greek\">ἄρτοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προσθέσεως</span> (em lugar de <span class=\"greek\">προθέσεως</span>) pães (sagrados) da proposição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:4</a> D=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:26</a> D=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:4</a> D, v. <span class=\"greek\">πρόθεσις</span> 1.—DELG s.v. <span class=\"greek\">τίθημι</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσκαιρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσκαιρος</span>, <span class=\"greek\">ον</span> (Strabo 7, 3, 11; Ael. Aristid. 46 p. 218 D. al.; OGI 669, 14 [I d.C.]; SIG 1109, 44; pap; 4 Macc 15:2, 8, 23; TestSol 5:5; TestAbr B 1 p. 105, 5 [Stone p. 58]; Jos., Bell. 5, 66, Ant. 2, 51; Just.; Mel., P. 2, 9 al.) que dura somente por algum tempo, temporário, transitório (Appian, Bell. Civ. 5, 43, §179) oposto a <span class=\"greek\">αἰώνιος</span> (Dionys. Hal., Ars Rhet. 7, 4; 6 <span class=\"greek\">ἀθάνατος</span>; Cass. Dio 12 Fgm. 46, 1 <span class=\"greek\">ἀί̈διος</span>), de coisas no mundo visível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:18</a> (Ps.-Clem., Hom. 2, 15 <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">παρὼν</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">πρόσκαιρος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐσόμενος</span> <span class=\"greek\">ἀί̈διος</span>; Pel.-Leg. p. 12, 26; JosAs 12:12 <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χρήματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span> <span class=\"greek\">Πεντεφρῆ</span> <span class=\"greek\">πρόσκαιρά</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀφανῆ</span>, <span class=\"greek\">τὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δώματα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κληρονομίας</span> <span class=\"greek\">σου</span>, <span class=\"greek\">κύριε</span>, <span class=\"greek\">ἄφθαρτά</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αἰώνια</span> ‘eis que todos os bens de meu pai P. são transitórios e evanescentes, mas as dádivas de tua herança, Senhor, são incorruptíveis e eternas’). <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀπόλαυσις</span> (v. <span class=\"greek\">ἀπόλαυσις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:25</a>. De perseguições <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. Dg 10:8. De pessoa: <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐστιν</span> dura somente um pouco de tempo (Dalman, PJ 22, 1926, 125f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:17</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκαλέω</span> (Soph., X., Pla.+; ins, pap, LXX; TestSol, TestAbr, Test12Patr; JosAs 23:2; AssMos Fgm. a) no grego fora de nossa literatura e na LXX predominantemente médio, em nossa literatura exclusivamente médio; fut. 3.ª sg. <span class=\"greek\">προσκαλέσεται</span> Ps. 49:4; 1.º aor. <span class=\"greek\">προσεκαλεσάμην</span>; perf. <span class=\"greek\">προσκέκλημαι</span>. Pass.: 1.º aor. 3.ª sg. <span class=\"greek\">προσεκλήθη</span> LXX; ‘convocar’.</p><p class=\"entry-text\">① chamar ou notificar a fim de obter a presença de alguém</p><p class=\"entry-text\">ⓐ de um chamado para estar na presença de quem fala: convocar, chamar, chamar para junto de si, convidar <span class=\"greek\">τινά</span> alguém (Gen 28:1; Esth 4:5; Sir 13:9; EpArist 182; Jos., Ant. 1, 271, Vi. 110; TestReub 4:9; AssMos p. 62 Denis [p. 272 Tromp]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:1</a>; 15:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:13</a>, 23; 6:7; 7:14; 15:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:18</a>; 15:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a>; 23:17f, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:14</a>; Hv 1, 4, 2; Hs 5, 2, 2; 6; 9, 7, 1; 9, 10, 6.</p><p class=\"entry-text\">ⓑ em sentido transferido do convite de Deus para participar dos benefícios da salvação: chamar (a) Deus ou Cristo, à fé etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:39</a> (cf. Jo 3:5). <span class=\"greek\">πρ</span>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> chamar por meio do Espírito Santo (isto é, por meio da Escritura inspirada) 1 Cl 22:1. De Cristo <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> (isto é, <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πάθει</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">προσκαλεῖται</span> <span class=\"greek\">ὑμᾶς</span> por meio do qual (isto é, da cruz), em seu sofrimento (ou morte; v. <span class=\"greek\">πάθος</span> 1, final), ele vos convoca ITr 11:2.</p><p class=\"entry-text\">② chamar em sentido jurídico ou oficial</p><p class=\"entry-text\">ⓐ como termo técnico jurídico (assim Aristoph., Lysias et al.; pap) chamar, convocar para interrogatório <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:40</a>. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:32</a>.</p><p class=\"entry-text\">ⓑ chamar para tarefa ou cargo especial—chamado feito pelo Espírito Santo <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ὸ̔</span> (=<span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔</span>) <span class=\"greek\">προσκέκλημαι</span> <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:2</a>. <span class=\"greek\">τινά</span> seguido de inf. <span class=\"greek\">εὐαγγελίσασθαι</span> 16:10.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκαρτερέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκαρτερέω</span> aor. part. pl. <span class=\"greek\">προσκαρτερήσαντες</span> Num. 13:20 (Demosth. et al.; SIG 717, 84; OGI 383, 130; 168 al.; pap, LXX; Jos., Bell. 6, 27)</p><p class=\"entry-text\">① permanecer junto de ou estar por perto, ligar-se a, servir, ser fiel a alguém, com dat. de pessoa e ênfase na continuidade (Ps.-Demosth. 59, 120; Polyb. 23, 5, 3; Diog. L. 8, 11, 14; PGiss 79 II, 9 [II d.C.]; PLond II, 196, 3 p. 153 [II d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:13</a>; 10:7, um ajudante militar. De um barco, estar à disposição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:9</a>.</p><p class=\"entry-text\">② persistir em algo</p><p class=\"entry-text\">ⓐ ocupar-se de, estar ativamente empenhado em, dedicar-se a, com dat. de coisa (<span class=\"greek\">τῇ</span> <span class=\"greek\">πολιορκίᾳ</span> Polyb. 1, 55, 4; Diod S 14, 87, 5; <span class=\"greek\">ταῖς</span> <span class=\"greek\">θήραις</span> Diod S 3, 17, 1; <span class=\"greek\">τῇ</span> <span class=\"greek\">καθέδρᾳ</span> Jos., Ant. 5, 130; <span class=\"greek\">τῇ</span> <span class=\"greek\">γεωργίᾳ</span> PAmh 65, 3; BGU 372 II, 15; PLond III, 904, 27 p. 125 [104 d.C.].—POxy 530, 9; PHamb 34, 9 [todos os pap do II d.C.]) <span class=\"greek\">τῇ</span> <span class=\"greek\">προσευχῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:4</a>. <span class=\"greek\">νηστείαις</span> Pol 7:2.—Em lugar do dat. <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:6</a>.—Seguido de <span class=\"greek\">ἐν</span> locativo: passar muito tempo em (Sus 6 Theod. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span>) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:46</a> (também com dat.: <span class=\"greek\">τῷ</span> <span class=\"greek\">ναῷ</span> no templo Did., Gen. 135, 23; Theoph. Ant. 3, 21 [p. 246, 3]). Sobre <span class=\"greek\">προσκαρτερέω</span> em Ac v. ESchürer, SBBerlAk 1897, 214f.</p><p class=\"entry-text\">ⓑ ater-se firmemente a, continuar em, perseverar em algo, com dat. de coisa (Polyb. 1, 59, 12 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιμελείᾳ</span>) <span class=\"greek\">τῇ</span> <span class=\"greek\">διδαχῇ</span> <span class=\"greek\">κτλ</span>. (Posidon.: 87 Fgm. 36, 48 Jac. <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span>=o ensino) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:42</a> (o sentido 2a também é provável). <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐλπίδι</span> Pol 8:1.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκαρτέρησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκαρτέρησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">προσκαρτερέω</span> 2; Philod., Rhet. I 11 S.; IPontEux II, 52; 53 [ambos do final do I d.C.]; EHicks, JTS 10, 1909, 571f; Dssm., LO 80 [LAE 100f]) persistência firme em um empreendimento ou circunstância, perseverança, paciência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:18</a>.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσκειμαι</h1><div class=\"entry-meta\"><span>verbo depoente defectivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσκειμαι</span> (Hom.+; ins, pap, LXX; JosAs [<span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> ‘manter fidelidade a, aderir a Deus’]; Jos., Bell. 2, 450; 542, Ant. 17, 225; Mel., P. 95, 727 [<span class=\"greek\">τίτλος</span> <span class=\"greek\">πρόσκειται</span> ‘a inscrição está afixada’]) depoente defectivo; com dat. de coisa: estar estreitamente ligado a, estar envolvido em, estar absorto em, dedicar-se a (Soph., Ajax 406; Thales em Diog. L. 1, 44; Paus. 4, 9, 3 <span class=\"greek\">μαντικῇ</span>; Thu. 7, 50, 4 e Plut., Nic. 525 [4, 1] <span class=\"greek\">θειασμῷ</span>; Jos., Ant. 12, 363) Hm 10, 1, 4.—Com dat. de pessoa <span class=\"greek\">πρόσκειται</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">ξένῳ</span> (Tecla) é adepta de um estrangeiro AcPl Ox 6, 10f (=Aa 1, 241, 13).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκεφάλαιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκεφάλαιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> objeto sobre o qual se pode repousar a cabeça, travesseiro (Aristoph., Hippocr. et al.; Diod S 13, 84, 6; Diog. L. 4, 37; pap; 1 Esdr 3:8; Ezk 13:18, 20) MPol 5:2; 12:3. Talvez a palavra tenha esse sentido também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:38</a>. Mas aqui o sentido de almofada de marinheiro é igualmente provável (Cratinus Com. [V a.C.] 269; SIG 736, 23 [92 a.C.]).—DELG s.v. <span class=\"greek\">κεφαλή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκληρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκληρόω</span> 1.º aor. pass. <span class=\"greek\">προσεκληρώθην</span> (Plut., Mor. 738d; Ps.-Lucian, Amor. 3; ‘atribuir por sorte, designar’) estar em estreita associação, estar ligado a, juntar-se a, com dat. de pessoa (v. OGI 257, 5 [109 a.C.] <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">προσκληθέντας</span> [v. nota de Dittenberger]; UPZ 144, 18 [II a.C.]; Philo, Sacr. Abel. 6, Exsecr. 162, Leg. ad Gai. 3; 68 <span class=\"greek\">τῶν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐκείνῳ</span> <span class=\"greek\">προσκληρουμένων</span>; Jos., Bell. 2, 567) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:4</a>.—DELG s.v. <span class=\"greek\">κλῆρος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0305-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσκλησις</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσκλησις</span> v. <span class=\"greek\">πρόσκλισις</span>.—M-M.</p></section></article>"};
